<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_login();$pageTitle='Draft Bookings';$s=db()->prepare('SELECT * FROM vw_booking_summary WHERE user_id=? AND status="draft" ORDER BY created_at DESC');$s->execute([$u['id']]);$rows=$s->fetchAll();$ns=db()->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$ns->execute([$u['id']]);$userUnreadNotifications=(int)$ns->fetchColumn();require __DIR__.'/../../includes/header.php';?><div class="admin-shell user-shell"><aside class="sidebar"><?php require __DIR__ . '/../sidebar.php'; ?></aside><section class="admin-content user-content"><section class="page-hero"><div class="container"><div class="eyebrow">Planning workspace</div><h1 class="page-title">Draft bookings.</h1><p>Continue, review or remove saved booking requests before submission.</p></div></section><section class="section"><div class="container"><div class="panel table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Event</th><th>Date</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['booking_ref'])?></td><td><?=e($r['event_title'])?></td><td><?=date('d M Y · H:i',strtotime($r['start_at']))?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><a class="btn btn-primary btn-sm" href="<?=url('user/bookings/view.php?id='.$r['id'])?>">Continue</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No saved drafts.</td></tr><?php endif;?></tbody></table></div></div></section></section></div><?php require __DIR__.'/../../includes/footer.php'; ?>
